model Product {
  id         Int         @id @default(autoincrement())
  name       String
  price      Float
  inventory  Int
  orderItems OrderItem[]
}

model Coupon {
  id    Int    @id @default(autoincrement())
  code  String @unique
  type  String // "PERCENT" or "FLAT"
  value Float  // 20 for 20% or 50 for $50
}

model Order {
  id         Int         @id @default(autoincrement())
  createdAt  DateTime    @default(now())
  subtotal   Float
  discount   Float
  total      Float
  couponCode String?
  orderItems OrderItem[]
}

model OrderItem {
  id        Int     @id @default(autoincrement())
  orderId   Int
  order     Order   @relation(fields: [orderId], references: [id])
  productId Int
  product   Product @relation(fields: [productId], references: [id])
  quantity  Int
  price     Float
}

