import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { getProducts, getCoupons } from "./src/queries" with { type: "ref" };
import { checkout, applyCouponCode } from "./src/actions" with { type: "ref" };
