import { createAction } from '../../middleware/operations.js'
import checkout from '../../actions/checkout.js'

export default createAction(checkout)

import { type Route } from "wasp/client";
import type {
  IfAny,
  _Awaited,
  _ReturnType,
} from "wasp/universal/types"

// PRIVATE API (for SDK, should maybe be public, users define values of this
// type).
//
// Frontend queries are functions with some extra properties (metadata).
// 
// To simplify working with the type (i.e., referencing the type's two different
// components), we've defined it as an intersection of two distinct types:
// one representing the function (QueryFunction), and the other representing the
// metadata (QueryMetadata) .
/**
 * The client Query object type. It's a callable Query function with some extra
 * properties (metadata).
 */
export type Query<Input, Output> = QueryFunction<Input, Output> & QueryMetadata

// PRIVATE API (for SDK, should maybe be public, users define values of this
// type)
/**
 * The client Action object type (unlike a Query, it's just a normal function).
 */
export type Action<Input, Output> = ClientOperation<Input, Output>

// PRIVATE API (for SDK)
/**
 * The client Query function type.
 */
export type QueryFunction<Input, Output> = ClientOperation<Input, Output>

// PRIVATE API (for SDK)
// todo: revisit what we expose. Also, queryCacheKey is confusing and
// incorrect.Details here: https://github.com/wasp-lang/wasp/issues/2017
/**
 *  All extra properties (metadata) found on a Query object type.
 */
export type QueryMetadata = {
  queryCacheKey: string[]
  route: Route
}

// PRIVATE API (needed in SDK)
// Explanation:
// - Custom `_Awaited` and `_ReturnType` - Read the comments above their
// definitions.
// - `Parameters<BackendOperation> extends []` - See here:
// https://github.com/wasp-lang/wasp/pull/1992/files#r1583040080
/**
 * Constructs the client RPC function type from the type of the operation's
 * definition on the backend.
 */
export type OperationRpcFor<BackendOperation extends GenericBackendOperation> =
  Parameters<BackendOperation> extends []
  ? ClientOperation<void, _Awaited<_ReturnType<BackendOperation>>>
  : ClientOperation<
    Parameters<BackendOperation>[0],
    _Awaited<_ReturnType<BackendOperation>>
  >

// PRIVATE API (needed in SDK)
/**
 * A supertype of all possible backend operation definitions (i.e., Queries and
 * Actions) 
 */
export type GenericBackendOperation = (args: never, context: any) => unknown

// PRIVATE API (needed in SDK)
/**
 * A supertype of all possible frontend RPC function types.
 */
export type GenericOperationRpc = (args: never) => Promise<unknown>

// NOTE: There's some duplication in the below types.
// Read the discussion here to understand why before trying to remove it:
// https://github.com/wasp-lang/wasp/pull/2170#discussion_r1671285049
//
// Read this to understand the type: https://github.com/wasp-lang/wasp/pull/2170#issue-2398830273
type ClientOperation<Input, Output> =
  IfAny<
    Input,
    (args?: any) => Promise<Output>,
    ClientOperationWithNonAnyInput<Input, Output>
  >

// Read this to understand the type: https://github.com/wasp-lang/wasp/pull/1090#discussion_r1159732471
type ClientOperationWithNonAnyInput<Input, Output> =
  [Input] extends [never]
  ? (args?: unknown) => Promise<Output>
  : [Input] extends [void]
  ? () => Promise<Output>
  : (args: Input) => Promise<Output>

import type { _Awaited, _ReturnType } from 'wasp/universal/types'
import type { OperationRpcFor, GenericBackendOperation } from '../rpc.js'
import { callOperation, makeOperationRoute } from '../internal/index.js'
import {
  registerActionInProgress,
  registerActionDone,
} from '../internal/resources.js'

// PRIVATE API
export function createAction<BackendAction extends GenericBackendOperation>(
  relativeActionRoute: string,
  entitiesUsed: unknown[]
): ActionFor<BackendAction> {
  const actionRoute = makeOperationRoute(relativeActionRoute)

  async function internalAction(args, specificOptimisticUpdateDefinitions) {
    registerActionInProgress(specificOptimisticUpdateDefinitions)
    try {
      // The `return await` is not redundant here. If we removed the await, the
      // `finally` block would execute before the action finishes, prematurely
      // registering the action as done.
      return await callOperation(actionRoute, args)
    } finally {
      await registerActionDone(entitiesUsed, specificOptimisticUpdateDefinitions)
    }
  }

  // We expose (and document) a restricted version of the API for our users,
  // while also attaching the full "internal" API to the exposed action. By
  // doing this, we can easily use the internal API of an action a users passes
  // into our system (e.g., through the `useAction` hook) without needing a
  // lookup table.
  //
  // While it does technically allow our users to access the interal API, it
  // shouldn't be a problem in practice. Still, if it turns out to be a problem,
  // we can always hide it using a Symbol.
  const action = (args) => internalAction(args, [])
  action.internal = internalAction

  // NOTE: I'm not sure why unknown is necessary here,
  // it might have something to do with functions allowing evolving types,
  // // while objects to not:
  // https://www.typescriptlang.org/play/?#code/MYewdgzgLgBCBGArGBeGBvGBDAXDA5AGYgj4wC+AUAogHTyoHxYBO+llA9JzIQK5hgUAJbhsAG3EgA7hGxgYAUwBuIccuFgA5jCgBPAA6KY8PrBqKhMACYhFcsCCiVQkWPwVoAFAEpUAPgJiUkoPekZ8ZjYgA
  return action as unknown as ActionFor<BackendAction>
}

// PRIVATE API
export type ActionFor<BackendAction extends GenericBackendOperation> =
  OperationRpcFor<BackendAction>

import { api, handleApiError } from 'wasp/client/api'
import { HttpMethod } from 'wasp/client'
import { serialize, deserialize } from 'wasp/core/serialization'

// PRIVATE API
export type OperationRoute = { method: HttpMethod.Post, path: string }

// PRIVATE API
export async function callOperation(operationRoute: OperationRoute, args: any) {
  try {
    const serializedArgs = serialize(args)
    const json = await api.post(operationRoute.path, {
      json: serializedArgs,
    }).json()
    return deserialize(json as any)
  } catch (error) {
    throw handleApiError(error)
  }
}

// PRIVATE API
export function makeOperationRoute(relativeOperationRoute: string): OperationRoute {
  return { method: HttpMethod.Post, path: `/${relativeOperationRoute}` }
}

import ky, { isHTTPError } from 'ky'
import { config } from 'wasp/client'
import { storage } from 'wasp/core/storage'
import { apiEventsEmitter } from './events.js'

const WASP_APP_AUTH_SESSION_ID_NAME = 'sessionId'

// PRIVATE API (sdk)
export function setSessionId(sessionId: string): void {
  storage.set(WASP_APP_AUTH_SESSION_ID_NAME, sessionId)
  apiEventsEmitter.emit('sessionId.set')
}

// PRIVATE API (sdk)
export function getSessionId(): string | null {
  const sessionId = storage.get(WASP_APP_AUTH_SESSION_ID_NAME) as
    | string
    | undefined
  return sessionId ?? null
}
// PRIVATE API (sdk)
export function clearSessionId(): void {
  storage.remove(WASP_APP_AUTH_SESSION_ID_NAME)
  apiEventsEmitter.emit('sessionId.clear')
}

// PRIVATE API (sdk)
export function removeLocalUserData(): void {
  storage.clear()
  apiEventsEmitter.emit('sessionId.clear')
}

// PUBLIC API
/**
 * A ky instance configured for the Wasp API server.
 *
 * Automatically prepends the API base URL, adds authentication headers,
 * and handles session invalidation on 401 responses. Non-2xx responses
 * cause ky to throw an `HTTPError`; pass it through `handleApiError` to
 * get a `WaspHttpError` carrying the server's status code, message, and
 * response body.
 */
export const api = ky.extend({
  prefix: config.apiUrl,
  hooks: {
    beforeRequest: [
      ({ request }) => {
        const sessionId = getSessionId()
        if (sessionId !== null) {
          request.headers.set('Authorization', `Bearer ${sessionId}`)
        }
      },
    ],
    afterResponse: [
      ({ request, response }) => {
        if (response.status === 401) {
          // Before clearing the session ID from local storage due to a 401 error,
          // compare the session ID stored in the *failed request's* headers
          // with the *current* session ID in local storage.
          // Only clear the local session ID if the two session IDs match.
          //
          // This prevents a race condition like this:
          // 1. Request A is sent with old session ID X.
          // 2. User logs out and logs back in, obtaining new session ID Y.
          // 3. Request A finally fails with a 401 (because ID X is invalid).
          // Without the check, we would clear the *current* valid session ID Y.
          // The check ensures we only clear the session if the *request that failed*
          // used the *same session ID that's currently stored*.
          const failingSessionId = getSessionIdFromAuthorizationHeader(
            request.headers.get('Authorization')
          )
          const currentSessionId = getSessionId()
          if (failingSessionId === currentSessionId) {
            clearSessionId()
          }
        }
      },
    ],
  },
})

// This makes sure that the following handler won't try to run in a non-browser
// environment (e.g. during SSR), where `window` is not defined.
if (typeof window !== 'undefined') {
  // This handler will run on other tabs (not the active one calling API functions),
  // and will ensure they know about auth session ID changes.
  // Ref: https://developer.mozilla.org/en-US/docs/Web/API/Window/storage_event
  // "Note: This won't work on the same page that is making the changes — it is really a way
  // for other pages on the domain using the storage to sync any changes that are made."
  window.addEventListener('storage', (event) => {
    if (event.key === storage.getPrefixedKey(WASP_APP_AUTH_SESSION_ID_NAME)) {
      if (!!event.newValue) {
        apiEventsEmitter.emit('sessionId.set')
      } else {
        apiEventsEmitter.emit('sessionId.clear')
      }
    }
  })
}

// PRIVATE API (sdk)
/**
 * Takes an error returned by the app's API (as thrown by ky), and transforms it into a more
 * standard format to be further used by the client. It is also assumed that given API
 * error has been formatted as implemented by HttpError on the server.
 */
export function handleApiError(error: unknown): unknown {
  if (isHTTPError(error)) {
    // If error came from HTTP response, we capture most informative message
    // and also add .statusCode information to it.
    // If error had JSON response, we assume it is of format { message, data } and
    // add that info to the error.
    // TODO: We might want to use HttpError here instead of just Error, since
    //   HttpError is also used on server to throw errors like these.
    //   That would require copying HttpError code to web-app also and using it here.
    const responseJson = error.data as { message?: string; data?: unknown } | undefined
    const responseStatusCode = error.response.status
    return new WaspHttpError(responseStatusCode, responseJson?.message ?? error.message, responseJson)
  } else {
    // If any other error, we just propagate it.
    return error
  }
}

class WaspHttpError extends Error {
  statusCode: number

  data: unknown

  constructor(statusCode: number, message: string, data: unknown) {
    super(message)
    this.statusCode = statusCode
    this.data = data
  }
}

function getSessionIdFromAuthorizationHeader(header: string | null): string | null {
  const prefix = 'Bearer '
  if (header && header.startsWith(prefix)) {
    return header.substring(prefix.length)
  } else {
    return null
  }
}

import { stripTrailingSlash } from '../universal/url.js'
import { env } from './env.js'

const apiUrl = stripTrailingSlash(env["REACT_APP_API_URL"])

// PUBLIC API
export type ClientConfig = {
  apiUrl: string,
}

// PUBLIC API
export const config: ClientConfig = {
  apiUrl,
}

import { deserialize, serialize } from "superjson"
import { CustomSerializableJSONValue } from "./custom-register"

import "./prisma"

export type Payload = void | SuperJSONValue;

// The part below was copied from SuperJSON and slightly modified:
// https://github.com/blitz-js/superjson/blob/ae7dbcefe5d3ece5b04be0c6afe6b40f3a44a22a/src/types.ts
//
// We couldn't use SuperJSON's types directly because:
//   1. They have a weird quirk that turns `SuperJSONValue` into `any`.
//      See why here:
//      https://github.com/blitz-js/superjson/pull/36#issuecomment-669239876
//   2. We need to add our own custom types to the serialization process.
//
// We changed the code as little as possible to make future comparisons easier.
export type JSONValue = PrimitiveJSONValue | JSONArray | JSONObject;

export interface JSONObject {
  [key: string]: JSONValue;
}

type PrimitiveJSONValue = string | number | boolean | undefined | null;

export interface JSONArray extends Array<JSONValue> {}

// Removed `Symbol` since we don't explicitly register any symbol to be serialized
// Added custom types from `CustomSerializableJSONValue`
export type SerializableJSONValue =
  | Set<SuperJSONValue>
  | Map<SuperJSONValue, SuperJSONValue>
  | undefined
  | bigint
  | Date
  | RegExp
  | CustomSerializableJSONValue;

// Here's where we excluded `ClassInstance` (which was `any`) from the union.
export type SuperJSONValue =
  | JSONValue
  | SerializableJSONValue
  | SuperJSONArray
  | SuperJSONObject;

export interface SuperJSONArray extends Array<SuperJSONValue> {}

export interface SuperJSONObject {
  [key: string]: SuperJSONValue;
}

export { deserialize, serialize }

